/* @autogenerated */
import { fakeAsync, tick } from '@angular/core/testing';
import { defer, of } from 'rxjs';
import { pollUntil, PollTimeoutError } from './poll-until';

describe('pollUntil', () => {
  it('polls with exponential backoff until done, emitting the final value', fakeAsync(() => {
    const responses = ['a', 'b', 'done'];
    const at: number[] = [];
    const start = Date.now();
    const request$ = defer(() => {
      at.push(Date.now() - start);
      return of(responses.shift()!);
    });
    const values: string[] = [];
    let completed = false;

    pollUntil(request$, (v) => v === 'done', { initial: 1000, factor: 2, max: 10_000 }).subscribe({
      next: (v) => values.push(v),
      complete: () => (completed = true),
    });

    tick(10_000);

    expect(values).toEqual(['a', 'b', 'done']);
    expect(at).toEqual([1000, 3000, 7000]);
    expect(completed).toBeTrue();
  }));

  it('caps the delay at max', fakeAsync(() => {
    let calls = 0;
    pollUntil(
      defer(() => of(++calls)),
      () => false,
      { initial: 1000, factor: 10, max: 2000, timeout: 7000 },
    ).subscribe({ error: () => undefined });

    tick(7000);
    // 1000, 3000, 5000, 7000 (timeout gana en el empate) → 3 consultas
    expect(calls).toBe(3);
  }));

  it('emits the onTimeout value and completes when the deadline passes', fakeAsync(() => {
    const values: string[] = [];
    let completed = false;
    pollUntil(of('pending'), () => false, {
      initial: 1000,
      timeout: 5000,
      onTimeout: (last) => 'timeout after ' + last,
    }).subscribe({ next: (v) => values.push(v), complete: () => (completed = true) });

    tick(5000);

    expect(values[values.length - 1]).toBe('timeout after pending');
    expect(completed).toBeTrue();
  }));

  it('errors with PollTimeoutError when no onTimeout is given', fakeAsync(() => {
    let error: unknown;
    pollUntil(of('pending'), () => false, { timeout: 3000 }).subscribe({ error: (e) => (error = e) });

    tick(3000);

    expect(error).toEqual(jasmine.any(PollTimeoutError));
  }));
});
